function canTrace(board, word) {
  const rows = board.length
  const cols = board[0].length
  const cells = board.map(row => row.split(''))
  const have = {}
  for (const row of board) for (const ch of row) have[ch] = (have[ch] || 0) + 1
  for (const ch of word) {
    if (!have[ch]) return false
    have[ch]--
  }
  const search = (r, c, i) => {
    if (r < 0 || c < 0 || r >= rows || c >= cols || cells[r][c] !== word[i]) return false
    if (i === word.length - 1) return true
    cells[r][c] = '#'
    const found = search(r + 1, c, i + 1) || search(r - 1, c, i + 1) || search(r, c + 1, i + 1) || search(r, c - 1, i + 1)
    cells[r][c] = word[i]
    return found
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (search(r, c, 0)) return true
    }
  }
  return false
}

