from collections import Counter


def can_trace(board, word):
    rows, cols = len(board), len(board[0])
    if Counter(word) - Counter(''.join(board)):
        return False
    cells = [list(row) for row in board]

    def search(r, c, i):
        if r < 0 or c < 0 or r >= rows or c >= cols or cells[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        cells[r][c] = '#'
        found = (search(r + 1, c, i + 1) or search(r - 1, c, i + 1)
                 or search(r, c + 1, i + 1) or search(r, c - 1, i + 1))
        cells[r][c] = word[i]
        return found

    return any(search(r, c, 0) for r in range(rows) for c in range(cols))
